var DATA = {"mode": "sensors", "list": [{"name": "CPU package temp", "val": 58, "unit": "C"}, {"name": "GPU temp", "val": 64, "unit": "C"}, {"name": "CPU package power", "val": 88, "unit": "W"}, {"name": "Fan 1", "val": 1150, "unit": "RPM"}]};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="sensors"){
  console.log("Sensors ("+DATA.list.length+"):");
  DATA.list.forEach(function(s){console.log("  "+s.name+": "+s.val+" "+s.unit);});
}else if(m==="stats"){
  var vs=DATA.vals,mn=Math.min.apply(null,vs),mx=Math.max.apply(null,vs);
  var avg=Math.round(vs.reduce(function(a,b){return a+b;},0)/vs.length*10)/10;
  show("Sensor",DATA.name);show("Min",mn+" "+DATA.unit);
  show("Max",mx+" "+DATA.unit);show("Average",avg+" "+DATA.unit);
}else if(m==="alert"){
  show("Sensor",DATA.name);
  show("Condition","trigger when >= "+DATA.th+" "+DATA.unit);
  show("Action",DATA.action);
  show("Would trip now",DATA.val>=DATA.th?"YES at "+DATA.val+" "+DATA.unit:"no ("+DATA.val+" "+DATA.unit+")");
}else if(m==="log"){
  show("File",DATA.file);show("Interval",DATA.ms+" ms");
  show("Rows per hour",Math.round(3600000/DATA.ms));
}else if(m==="osd"){
  show("Overlay",DATA.what);
  show("Feed","RTSS shared memory");
  show("Layout",DATA.layout);
}else if(m==="power"){
  show("CPU package",DATA.cpu+" W");
  show("GPU board",DATA.gpu+" W");
  show("Combined",(DATA.cpu+DATA.gpu)+" W");
}else if(m==="fans"){
  DATA.fans.forEach(function(f){console.log("  "+f.name+": "+f.rpm+" RPM ("+f.pct+"%)");});
}else if(m==="volts"){
  DATA.rails.forEach(function(r){console.log("  "+r.name+": "+r.v+" V");});
}else if(m==="summary"){
  console.log("System summary: "+DATA.cpu+" / "+DATA.gpu+" / "+DATA.ram);
}else if(m==="report"){
  show("Report",DATA.file);show("Format",DATA.fmt);
  show("Sections",DATA.sections);
}else if(m==="poll"){
  show("Polling period",DATA.ms+" ms");
  show("Trade-off","faster = smoother graphs, slightly more CPU");
}else if(m==="custom"){
  show("Custom sensor",DATA.name);
  show("Formula",DATA.formula);
  show("Result",DATA.result+" "+DATA.unit);
}else if(m==="compare"){
  show("Reading A",DATA.a+" "+DATA.unit);
  show("Reading B",DATA.b+" "+DATA.unit);
  show("Delta",(Math.round((DATA.b-DATA.a)*10)/10)+" "+DATA.unit);
}else if(m==="workflow"){
  console.log("Monitoring workflow:");
  DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}
